            lines++;
            if (cur_len > maxlen)
                maxlen = cur_len;
            cur_len = 0;
            in_word = 0;
        } else if (is_ws(c)) {
            /* \r is whitespace for word-counting but contributes to line length for maxlen */
            if (in_word) {
                words++;
                in_word = 0;
            }
        }

        cur_len++;
    }

    /* If the final "line" has no trailing newline, its length is still in cur_len.
