#include <stdio.h>

/* A '\r' ends a word but is counted toward line length (ordinary byte for maxlen). */
static int is_ws(int c) {
    return c == ' ' || c == '\t' || c == '\v' || c == '\f' || c == '\r';
}

int main(void)
{
    int c;
    long lines = 0;
    long words = 0;
    long bytes = 0;
    long maxlen = 0;
    long cur_len = 0;   /* length of current line (no \n counted) */

    /* in_word=1 when currently scanning characters that are part of a word.
       starts_new_word=1 means the *next* non-ws character we see will be the
       first byte of a new word (i.e. it is preceded by whitespace or EOF). */
    int in_word = 0;
    int starts_new_word = 1;

    while ((c = getchar()) != EOF) {
        bytes++;

        if (c == '\n') {
            lines++;
            if (cur_len > maxlen)
                maxlen = cur_len;
            cur_len = 0;
            in_word = 0;
            starts_new_word = 1;
        } else if (is_ws(c)) {
            /* Whitespace between words */
            if (in_word) {
                words++;
                in_word = 0;
            }
            starts_new_word = 1;
            cur_len++;
        } else {
            if (!in_word) {
                if (starts_new_word) {
                    words++;
                }
                in_word = 1;
            }
            /* c is \r here — it counts toward line length */
            cur_len++;
        }
    }

    /* Finalize: the last "line" length needs comparing to maxlen. */
    if (bytes > 0 && cur_len > maxlen) {
        maxlen = cur_len;
    }

    /* If we ended while still inside a word at EOF, count it. */
    if (in_word) {
        words++;
        in_word = 0;
    }

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
}

